## Why This Is Asked
Explores a new DP angle: subarray-level min as value, exact k non-overlapping blocks, with clear reconstruction.

## Key Concepts
- Partition DP with exact block count
- Precomputation of subarray minima
- Backtracking to obtain endpoints

## Code Example
```javascript
// Assumes A is 1-indexed, n = A.length-1, k given
function maxSumMinSubarrays(A, n, k) {
  const M = Array.from({length: n+2}, ()=>Array(n+2).fill(0));
  for (let l=1; l<=n; l++) {
    let m = A[l];
    for (let r=l; r<=n; r++) {
      m = Math.min(m, A[r]);
      M[l][r] = m;
    }
  }
  const dp = Array.from({length: n+1}, ()=>Array(k+1).fill(-Infinity));
  const opt = Array.from({length: n+1}, ()=>Array(k+1).fill(-1));
  dp[0][0] = 0;
  for (let i=1; i<=n; i++) {
    for (let t=1; t<=k; t++) {
      for (let l=1; l<=i; l++) {
        const cand = dp[l-1][t-1] + M[l][i];
        if (cand > dp[i][t]) { dp[i][t] = cand; opt[i][t] = l; }
      }
    }
  }
  // backtrack for endpoints
  let i = n, t = k, blocks = [];
  while (t > 0) {
    const l = opt[i][t];
    blocks.push([l, i]);
    i = l-1; t--;
  }
  blocks.reverse();
  return {sum: dp[n][k], blocks};
}
```

## Why This Is Asked
Tests DP with subarray composition where each block incurs a fixed cost, a realistic pattern in scheduling/payments. It also checks reconstruction of intervals.

## Key Concepts
- Prefix sums to compute subarray sums fast
- DP over positions and block counts
- Optimization: collapse inner max with a running best value per t
- Backpointer reconstruction for endpoints

## Code Example
```javascript
function maxKSubarraySumMinusC(A, k, c) {
  const n = A.length;
  const pref = Array(n+1).fill(0);
  for (let i=1; i<=n; i++) pref[i] = pref[i-1] + A[i-1];
  const dp = Array.from({length: n+1}, ()=> Array(k+1).fill(-1e15));
  const endAt = Array.from({length: n+1}, ()=> Array(k+1).fill(null));
  dp[0][0] = 0;
  const bestVal = Array(k+1).fill(-1e15);
  const bestIdx = Array(k+1).fill(-1);
  bestVal[1] = 0; bestIdx[1] = 1; // allow start at 1 for first block
  for (let i=1; i<=n; i++) {
    for (let t=1; t<=k; t++) {
      const endVal = pref[i] - c + bestVal[t];
      if (dp[i-1][t] >= endVal) {
        dp[i][t] = dp[i-1][t];
      } else {
        dp[i][t] = endVal;
        endAt[i][t] = {start: bestIdx[t], end: i};
      }
    }
    for (let t=1; t<=k; t++) {
      const cand = dp[i][t-1] - pref[i];
      if (cand > bestVal[t]) { bestVal[t] = cand; bestIdx[t] = i+1; }
    }
  }
  const blocks = [];
  let i = n, t = k;
  while (t > 0 && i > 0) {
    const e = endAt[i][t];
    if (e) { blocks.push([e.start, e.end]); i = e.start - 1; t--; }
    else { i--; }
  }
  blocks.reverse();
  return { value: dp[n][k], blocks };
}
```

## Follow-up Questions
- How would you adapt for at most k blocks or variable per-block cost?
- How does the reconstruction change if ties occur on values?

## Why This Is Asked

Tests dynamic programming on partitioning a string into numeric substrings, including numeric parsing and reconstruction, a common interview pattern.

## Key Concepts

- DP on string partitions with exact k blocks
- Efficient substring value computation and leading-zero handling
- Path reconstruction via parent pointers
- Time/space trade-offs: O(n^2 k) time, O(nk) space

## Code Example

```javascript
function maxSumPartition(s, k) {
  const n = s.length;
  // val[i][j] = value of s[i..j-1]
  const val = Array.from({ length: n+1 }, () => Array(n+1).fill(0));
  for (let i = 0; i < n; i++) {
    if (s[i] === '0') { val[i][i+1] = 0; continue; }
    let cur = 0;
    for (let j = i; j < n; j++) {
      cur = cur*10 + (s.charCodeAt(j) - 48);
      val[i][j+1] = cur;
    }
  }
  const dp = Array.from({ length: n+1 }, () => Array(k+1).fill(-Infinity));
  const par = Array.from({ length: n+1 }, () => Array(k+1).fill(-1));
  for (let i = 1; i <= n; i++) dp[i][1] = val[0][i];
  for (let t = 2; t <= k; t++) {
    for (let i = t; i <= n; i++) {
      for (let j = t-1; j < i; j++) {
        if (s[j] === '0' && i - j > 1) continue;
        const cand = dp[j][t-1] + val[j][i];
        if (cand > dp[i][t]) { dp[i][t] = cand; par[i][t] = j; }
      }
    }
  }
  // reconstruct cuts
  const cuts = [];
  let i = n, t = k;
  while (t > 0) {
    const j = par[i][t];
    cuts.push(i);
    i = j;
    t--;
  }
  cuts.push(0);
  cuts.reverse();
  return { sum: dp[n][k], cuts };
}
```

## Follow-up Questions

- How would you adapt to allow at most k blocks instead of exactly k?
- How would you optimize for very large n or larger k (space/time optimizations, early pruning)?

## Why This Is Asked
New DP angle focusing on subarray range gain with exact k partitions.

## Key Concepts
- DP partitioning
- Precomputing range max/min
- Reconstruction through pointers
- Time: O(n^2 k); Space: O(nk)

## Code Example
```javascript
function maxGainKSubarrays(A, k){
  const n = A.length;
  const gain = Array.from({length:n}, ()=>Array(n).fill(0));
  for(let l=0;l<n;l++){
    let mn = A[l], mx = A[l];
    for(let r=l;r<n;r++){
      mn = Math.min(mn, A[r]);
      mx = Math.max(mx, A[r]);
      gain[l][r] = mx - mn;
    }
  }
  const dp = Array.from({length:n+1}, ()=>Array(k+1).fill(-Infinity));
  const take = Array.from({length:n+1}, ()=>Array(k+1).fill(-1));
  dp[0][0] = 0;
  for(let i=1;i<=n;i++){
    for(let t=0;t<=Math.min(i,k);t++){
      dp[i][t] = dp[i-1][t];
      take[i][t] = take[i-1][t];
      if(t>0){
        for(let l=1;l<=i;l++){
          const val = dp[l-1][t-1] + gain[l-1][i-1];
          if(val>dp[i][t]){ dp[i][t] = val; take[i][t] = l-1; }
        }
      }
    }
  }
  const res = [];
  let i=n, t=k;
  while(t>0){
    const lminus1 = take[i][t];
    const l = lminus1 + 1;
    res.unshift([l, i]);
    i = lminus1; t--;
  }
  return {score: dp[n][k], blocks: res};
}
```

## Follow-up Questions
- How would you optimize memory to O(nk) and still reconstruct blocks?
- How would the solution change if subarrays must have at least a fixed length L?

## Why This Is Asked
Tests partition DP with a subarray range cost, requiring precomputation of subarray extrema and careful reconstruction. It adds a different objective than prior questions by using (max-min) rather than a function of endpoints or a fixed multiplier. 

## Key Concepts
- DP over partitions with exact-k segments
- Subarray range queries (max-min) via precomputation
- Path reconstruction from parent pointers
- Time/space trade-offs for small to mid-size n

## Code Example
```javascript
function minCostPartition(A, k) {
  const n = A.length;
  const maxv = Array.from({length: n}, () => Array(n).fill(0));
  const minv = Array.from({length: n}, () => Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    maxv[i][i] = A[i];
    minv[i][i] = A[i];
    for (let j = i + 1; j < n; j++) {
      maxv[i][j] = Math.max(maxv[i][j-1], A[j]);
      minv[i][j] = Math.min(minv[i][j-1], A[j]);
    }
  }
  const INF = 1e18;
  const dp = Array.from({length: n+1}, () => Array(k+1).fill(INF));
  const par = Array.from({length: n+1}, () => Array(k+1).fill(-1));
  dp[0][0] = 0;
  for (let i = 1; i <= n; i++) dp[i][1] = (maxv[0][i-1]-minv[0][i-1]) * i, par[i][1] = 0;
  for (let t = 2; t <= k; t++) {
    for (let i = t; i <= n; i++) {
      for (let p = t-1; p <= i-1; p++) {
        const cost = (maxv[p][i-1]-minv[p][i-1]) * (i-p);
        if (dp[p][t-1] + cost < dp[i][t]) {
          dp[i][t] = dp[p][t-1] + cost;
          par[i][t] = p;
        }
      }
    }
  }
  let idx = n, rem = k, cuts = [];
  while (rem > 0) {
    const p = par[idx][rem];
    cuts.push([p, idx-1]);
    idx = p; rem--;
  }
  cuts.reverse();
  return {cost: dp[n][k], blocks: cuts};
}
```

## Why This Is Asked
Tests ability to extend Kadane-like DP to k non-overlapping segments with per-element penalties and reconstruction of exact endpoints.

## Key Concepts
- DP for k disjoint subarrays with penalties
- Local/global state separation for endings vs global maxima
- Backpointer reconstruction to recover endpoints
- Time complexity O(nk), space O(nk)

## Code Example
```javascript
function maxKSubarrays(A, k, p) {
  const n = A.length;
  const negInf = -1e18;
  const local = Array.from({ length: n + 1 }, () => Array(k + 1).fill(negInf));
  const global = Array.from({ length: n + 1 }, () => Array(k + 1).fill(negInf));
  global[0][0] = 0;
  // backpointers omitted for brevity in this snippet
  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= k; t++) {
      const val = A[i - 1] - p;
      local[i][t] = Math.max(local[i - 1][t] + val, global[i - 1][t - 1] + val);
      global[i][t] = Math.max(global[i - 1][t], local[i][t]);
    }
  }
  return { maxValue: global[n][k], endpoints: [] };
}
```

